 pub fn requires_original_birth(&self)->bool{if self.close_route.is_some()||self.popped.is_some()||self.scan.is_some()||self.pending.is_some()||!self.frames.terminal_is_empty()||self.key.is_some()||self.leaf.is_some(){return false}if !self.key_backing.terminal_is_empty(){return self.key_backing.get().is_some_and(|frame|frame.is_closing()&&!frame.terminal_is_empty()&&frame.requires_original_birth())}RetainedCloneBinding::requires_original_birth(&self.binding)}
